  floodNeighbourBoundMs: { unit: "ms", why: "beside a flooding terminal, a key's echo in another terminal and a control call are answered within this under any load (a hard bound, about four times the worst p99 read on a loaded machine, 26.4 ms; the budget for a quiet machine is P-TERM-2)" },
  checkpointMaxAgeMs: { unit: "ms", why: "dirty mirror checkpointed after this long" },
  checkpointRingFraction: { unit: "ratio", why: "dirty mirror checkpointed after this fraction of a ring of output" },
  checkpointQuietMs: { unit: "ms", why: "no serialisation within this long after a keystroke to the visible terminal" },
  checkpointMinIntervalMs: { unit: "ms", why: "at most one serialisation per this interval" },
  resizeDebounceMs: { unit: "ms", why: "resizes debounced" },
  ptyMinCols: { unit: "cols", why: "smallest PTY width" },
  ptyMinRows: { unit: "rows", why: "smallest PTY height" },
  ptyDefaultCols: { unit: "cols", why: "a background start's width before any grid was reported" },
  ptyDefaultRows: { unit: "rows", why: "a background start's height before any grid was reported" },
  shellEnvTimeoutMs: { unit: "ms", why: "login-shell environment resolution timeout" },
  shellEnvOutputMaxBytes: { unit: "bytes", why: "a login shell printing more than this is cut off and the next fallback is tried" },
  terminalRecordsMax: { unit: "count", why: "shell tabs' terminal records, kept in terminals.json; the oldest ended records are dropped first" },
  instanceLockTimeoutMs: { unit: "ms", why: "Linux's instance lock: util-linux's `flock --nonblock` on the lock's descriptor answers at once; past this the lock is not taken and the process says why" },
  processProbeTimeoutMs: { unit: "ms", why: "the one `kea-helper procs` run that reads holder pids' start times and executables (pid-reuse check), and the one that lists the processes for the helper-copy pruning" },
  mirrorParkIdleMs: { unit: "ms", why: "mirror with no renderer and no output this long is parked" },
  mirrorStallMs: { unit: "ms", why: "write callback silent this long with data pending → mirror rebuilt" },
  holderReadoptIntervalMs: { unit: "ms", why: "a holder connection that closes while its PTY runs is re-adopted at once, at most once per this interval; closing again sooner reports the PTY lost (a holder that keeps dropping ptyhost)" },
  repaintNudgeMs: { unit: "ms", why: "delay between the rows−1 and restore resizes of the alt-screen repaint nudge" },
  holderConnectTimeoutMs: { unit: "ms", why: "connect + HELLO to a holder; longer than holder_peer_check_timeout_ms so a slow admitting check is not taken for a dead holder" },
  snapshotSyncWaitMs: { unit: "ms", why: "a snapshot or checkpoint waits at most this long for an open DEC 2026 block to close" },
  shellCloseGraceMs: { unit: "ms", why: "a closed shell tab's session is hung up; anything still alive this long after is terminated" },
  tabTitleStatMs: { unit: "ms", why: "a shell tab on screen asks its holder what runs in the foreground (`STAT`) at most once in this long when its output starts or a key is typed (a pause of its output is asked at once)" },
